/* eslint-disable eqeqeq */
import { Component, OnInit, ViewChild } from '@angular/core';
import { DomSanitizer, SafeUrl } from '@angular/platform-browser';
import { AlertController, IonContent, LoadingController, ToastController } from '@ionic/angular';
import { SharedIonic } from '../../../../core/common/SharedIonic';
import { Urls } from '../../../../core/common/Urls';
import { GResponse } from '../../../../core/common/GResponse';
import { FormBuilder, FormGroup, Validators } from '@angular/forms';
import { Router } from '@angular/router';
import { CourseService } from 'src/app/data/service/course/course.service';
import { SliderService } from 'src/app/data/service/site/Slider.service';
import { G } from '../../../../core/common/G';

@Component({
  selector: 'app-whp-to-hp',
  templateUrl: './whp-to-hp.component.html',
  styleUrls: ['./whp-to-hp.component.scss']
})
export class WhpToHpComponent implements OnInit {

  @ViewChild(IonContent) content: IonContent;

  isShow = false;
  isCheck = true;
  queryText = '';
  showSearchbar = false;
  instagram: string | SafeUrl = '';
  twiter: string | SafeUrl = '';
  facebook: string | SafeUrl = '';
  telegram: string | SafeUrl = '';
  pinterest: string | SafeUrl = '';
  aparat: string | SafeUrl = '';
  discord: string | SafeUrl = '';
  youtube: string | SafeUrl = '';
  twitch: string | SafeUrl = '';
  linkedin: string | SafeUrl = '';
  tunerPlusVideo: string | SafeUrl = 'nvkzf';

  form: FormGroup;
  res = 133.3;
  selectedHp = 1;
  selectedDefr = 1;
  selectedGear = 1;

  constructor(
    private fb: FormBuilder,
    private router: Router,
    public alertController: AlertController,
    private sanitizer: DomSanitizer,
    public loadingController: LoadingController,
    public toastController: ToastController,
    private courseService: CourseService,
    private siteService: SliderService
  ) {
    this.isShow = false;
    this.check();
  }

  async check() {

    SharedIonic.loading(this.loadingController);

    this.siteService.GetTunerPlusById(15).subscribe(
      res => {
        if (res.status === GResponse.SuccessStatus) {

          if (res.data.isActive) {

            if (!res.data.isFree) {

              this.courseService.GetUserCoursesId().subscribe(
                ress => {
                  if (ress.status === GResponse.SuccessStatus) {
                    let found = false;
                    res.data.courseIds.forEach(courseId => {

                      if (ress.data.find(n => n == courseId)) {
                        found = true;

                        this.courseService.GetUserTunerPlusAccess().subscribe(
                          resss => {
                            if (resss.status === GResponse.SuccessStatus) {

                              SharedIonic.dismissLoading(this.loadingController);
                              this.isCheck = false;

                            } else {
                              this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
                              SharedIonic.dismissLoading(this.loadingController);
                            }
                          },
                          errs => {
                            this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
                            SharedIonic.dismissLoading(this.loadingController);
                          }
                        );
                      }
                    });

                    if (!found) {
                      this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
                      SharedIonic.dismissLoading(this.loadingController);
                    }

                  } else {
                    this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
                    SharedIonic.dismissLoading(this.loadingController);
                  }
                },
                errs => {
                  this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
                  SharedIonic.dismissLoading(this.loadingController);
                }
              );
            } else {
              SharedIonic.dismissLoading(this.loadingController);
              this.isCheck = false;
            }
          } else {
            this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
            SharedIonic.dismissLoading(this.loadingController);
          }
        } else {
          this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
          SharedIonic.dismissLoading(this.loadingController);
        }
      },
      err => {
        this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
        SharedIonic.dismissLoading(this.loadingController);
      }
    );
  }

  onHpSelected(event): void {

    this.selectedHp = +event.detail.value;
  }

  onDefrSelected(event): void {

    this.selectedDefr = +event.detail.value;
  }

  onGearSelected(event): void {

    this.selectedGear = +event.detail.value;
  }

  goTop() {
    this.content.scrollToTop(3000);
  }

  forwardUrl(url: string) {
    window.location.href = url;
  }

  onNavigate(url: string) {

    this.router.navigateByUrl(url);
  }

  onCancel() {
    this.showSearchbar = false;
  }

  search() {

    if (this.queryText == null || this.queryText.length < 1) {
      return;
    }

    this.router
      .navigate(
        ['Home', 'Search'],
        {
          queryParams:
          {
            title: this.queryText
          }
        });
  }

  ngOnInit(): void {

    this.instagram = G.Instagram;
    this.twiter = G.Twiter;
    this.facebook = G.Facebook;
    this.telegram = G.Telegram;
    this.youtube = G.Youtube;
    this.pinterest = G.Pinterest;
    this.linkedin = G.Linkedin;
    this.twitch = G.Twitch;
    this.aparat = G.Aparat;
    this.discord = G.Discord;
    this.tunerPlusVideo = G.WhpToHpVideo;

    this.form = this.fb.group({
      hp: [110, [Validators.required, Validators.min(50), Validators.max(20000)]]
    });
  }

  onCalc() {

    SharedIonic.loading(this.loadingController);

    this.courseService.GetUserTunerPlusAccess().subscribe(
      resss => {
        if (resss.status === GResponse.SuccessStatus) {

          if (this.form.valid) {

            if (this.selectedHp == 2) {

              switch (this.selectedDefr) {
                case 1:
                  switch (this.selectedGear) {
                    case 1:
                      this.res = (+this.form.value.hp * 0.9) - 10;
                      break;
                    case 2:
                      this.res = (+this.form.value.hp * 0.88) - 9.9732;
                      break;
                    case 3:
                      this.res = (+this.form.value.hp * 0.8497) - 9.6952;
                      break;

                    default:
                      this.res = 0;
                      break;
                  }
                  break;
                case 2:
                  switch (this.selectedGear) {
                    case 1:
                      this.res = (+this.form.value.hp * 0.88) - 9.9732;
                      break;
                    case 2:
                      this.res = (+this.form.value.hp * 0.86) - 9.9512;
                      break;
                    case 3:
                      this.res = (+this.form.value.hp * 0.829) - 9.9122;
                      break;

                    default:
                      this.res = 0;
                      break;
                  }
                  break;
                case 3:
                  switch (this.selectedGear) {
                    case 1:
                      this.res = (+this.form.value.hp * 0.86) - 9.9512;
                      break;
                    case 2:
                      this.res = (+this.form.value.hp * 0.84) - 10.049;
                      break;
                    case 3:
                      this.res = (+this.form.value.hp * 0.8098) - 9.8758;
                      break;

                    default:
                      this.res = 0;
                      break;
                  }
                  break;
                case 4:
                  switch (this.selectedGear) {
                    case 1:
                      this.res = (+this.form.value.hp * 0.84) - 10.049;
                      break;
                    case 2:
                      this.res = (+this.form.value.hp * 0.82) - 10.027;
                      break;
                    case 3:
                      this.res = (+this.form.value.hp * 0.79) - 9.9926;
                      break;

                    default:
                      this.res = 0;
                      break;
                  }
                  break;
                default:
                  this.res = 0;
                  break;
              }
            } else {
              switch (this.selectedDefr) {
                case 1:
                  switch (this.selectedGear) {
                    case 1:
                      this.res = (+this.form.value.hp + 10) / 0.9;
                      break;
                    case 2:
                      this.res = (+this.form.value.hp + 9.9732) / 0.88;
                      break;
                    case 3:
                      this.res = (+this.form.value.hp + 9.6952) / 0.8497;
                      break;

                    default:
                      this.res = 0;
                      break;
                  }
                  break;
                case 2:
                  switch (this.selectedGear) {
                    case 1:
                      this.res = (+this.form.value.hp + 9.9732) / 0.88;
                      break;
                    case 2:
                      this.res = (+this.form.value.hp + 9.9512) / 0.86;
                      break;
                    case 3:
                      this.res = (+this.form.value.hp + 9.9122) / 0.829;
                      break;

                    default:
                      this.res = 0;
                      break;
                  }
                  break;
                case 3:
                  switch (this.selectedGear) {
                    case 1:
                      this.res = (+this.form.value.hp + 9.9512) / 0.86;
                      break;
                    case 2:
                      this.res = (+this.form.value.hp + 10.049) / 0.84;
                      break;
                    case 3:
                      this.res = (+this.form.value.hp + 9.8758) / 0.8098;
                      break;

                    default:
                      this.res = 0;
                      break;
                  }
                  break;
                case 4:
                  switch (this.selectedGear) {
                    case 1:
                      this.res = (+this.form.value.hp + 10.049) / 0.84;
                      break;
                    case 2:
                      this.res = (+this.form.value.hp + 10.027) / 0.82;
                      break;
                    case 3:
                      this.res = (+this.form.value.hp + 9.9926) / 0.79;
                      break;

                    default:
                      this.res = 0;
                      break;
                  }
                  break;
                default:
                  this.res = 0;
                  break;
              }
            }

            this.res = +this.res.toFixed(1);
          }
          SharedIonic.dismissLoading(this.loadingController);

        } else {
          this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
          SharedIonic.dismissLoading(this.loadingController);
        }
      },
      errs => {
        this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
        SharedIonic.dismissLoading(this.loadingController);
      }
    );

  }

  onReset() {

    this.res = 133.3;
    this.form.setValue({
      hp: 110
    });
  }

  onInfo(type: string) {

    switch (type) {
      case 'hp':
        this.presentActiveAlertConfirm('توان برحسب اسب بخار');
        break;

      default:
        break;
    }
  }

  async presentActiveAlertConfirm(msg: string = '') {
    const alert = await this.alertController.create({
      cssClass: 'main-alert',
      header: 'توضیحات',
      message: msg,
      buttons: [
        {
          text: 'بستن',
          role: 'cancel',
          cssClass: 'secondary',
          handler: () => {
          }
        }
      ]
    });

    await alert.present();
  }

  checkURL() {
    const url = 'https://www.aparat.com/video/video/embed/videohash/' +
      this.tunerPlusVideo +
      '/vt/frame';

    return this.sanitizer.bypassSecurityTrustResourceUrl(url);
  }

  checkVideoUrl() {
    const url = 'https://www.aparat.com/v/' +
      this.tunerPlusVideo;

    return this.sanitizer.bypassSecurityTrustResourceUrl(url);
  }
}
